// Reference solution
function parseStatusLine(line) {
  var m = /^HTTP\/(\d(?:\.\d)?) (\d{3})(?: (.*))?$/.exec(String(line).trim());
  if (!m) return null;
  return { version: m[1], status: Number(m[2]), reason: m[3] || '' };
}

