/** curl -i output ⇒ { name: value } (names lower-case) */
function parseHeaders(text) {
  // Write your solution here
  var out = {};
  text.split('\n').forEach(function (line) {
    var p = line.split(':');
    if (p.length > 1) out[p[0]] = p[1].trim();
  });
  return out;
}

